import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/axios';
import styles from './Showtimes.module.css';

export default function Showtimes() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [movie, setMovie] = useState(null);
  const [showtimes, setShowtimes] = useState([]);
  const [selectedDate, setSelectedDate] = useState('');

  // Generate next 7 days
  const dates = Array.from({ length: 7 }, (_, i) => {
    const d = new Date();
    d.setDate(d.getDate() + i);
    return d.toISOString().split('T')[0];
  });

  useEffect(() => {
    setSelectedDate(dates[0]);
    api.get(`/movies/${id}`).then(({ data }) => setMovie(data)).catch(console.error);
  }, [id]);

  useEffect(() => {
    if (selectedDate) {
      api.get('/showtimes', { params: { movieId: id, date: selectedDate } })
        .then(({ data }) => setShowtimes(data))
        .catch(console.error);
    }
  }, [id, selectedDate]);

  return (
    <div className={styles.container}>
      {movie && <h2>{movie.title} — Select Showtime</h2>}

      <div className={styles.dates}>
        {dates.map((d) => (
          <button
            key={d}
            className={selectedDate === d ? styles.active : ''}
            onClick={() => setSelectedDate(d)}
          >
            {new Date(d).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
          </button>
        ))}
      </div>

      {showtimes.length === 0 ? (
        <p className={styles.empty}>No showtimes available for this date.</p>
      ) : (
        <div className={styles.list}>
          {showtimes.map((st) => (
            <div key={st._id} className={styles.card}>
              <div>
                <p className={styles.theater}>{st.theater} — {st.screen}</p>
                <p className={styles.time}>{st.startTime} – {st.endTime}</p>
                <p className={styles.price}>
                  Regular ₹{st.regularPrice} | Premium ₹{st.premiumPrice} | VIP ₹{st.vipPrice}
                </p>
              </div>
              <button className={styles.btn} onClick={() => navigate(`/showtimes/${st._id}/seats`)}>
                Select Seats
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
